arguments.prompt:
You are building a Blazor Web App for a logistics company that tracks shipments. The project is already scaffolded at `/tmp/sv-ee8327ab46f544cf97ca63ff6240c3ec` with:
- Server project: `ShipmentTracker/`  
- Client project: `ShipmentTracker.Client/`
- Auto render mode (Server + WebAssembly) with Individual accounts auth
- .NET 10, SQLite database, EF Core Identity already configured

## Architecture

Since this is Auto render mode, pages run on Server first (fast initial load) then WebAssembly (no round-trips). The Client project can't access the DB directly, so we need:
- Shared models in the Client project
- An `IShipmentService` interface in the Client project
- Server-side implementation that queries EF Core directly
- Client-side (WASM) implementation that calls HTTP API endpoints
- Minimal API endpoints on the server

## What to Build

### 1. Shared Models — `ShipmentTracker.Client/Models/`

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed,
    Returned
}
```

### 2. Service Interface — `ShipmentTracker.Client/Services/IShipmentService.cs`
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> GetByIdAsync(int id);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentAsync(Shipment shipment);
}
```

### 3. Client-side HTTP Implementation — `ShipmentTracker.Client/Services/ClientShipmentService.cs`
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment?> GetByIdAsync(int id)
    {
        var response = await http.GetAsync($"api/shipments/{id}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 4. Register client services — Update `ShipmentTracker.Client/Program.cs`

The current file likely has minimal content. It needs to register `ClientShipmentService` and `HttpClient`:
```csharp
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ClientShipmentService>();

await builder.Build().RunAsync();
```

### 5. Server-side Shipment entity in DB — `ShipmentTracker/Data/`

Update `ShipmentTracker/Data/ApplicationDbContext.cs` to add a Shipments DbSet. Use a separate entity class that mirrors the shared model:

```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });
    }
}
```

### 6. Server-side service — `ShipmentTracker/Services/ServerShipmentService.cs`
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
        => await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<Shipment?> GetByIdAsync(int id)
        => await db.Shipments.FindAsync(id);

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";
        shipment.CreatedDate = DateTime.UtcNow;
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var existing = await db.Shipments.FindAsync(shipment.Id)
            ?? throw new InvalidOperationException("Shipment not found");
        existing.Status = shipment.Status;
        existing.Destination = shipment.Destination;
        existing.Origin = shipment.Origin;
        existing.EstimatedDelivery = shipment.EstimatedDelivery;
        existing.ActualDelivery = shipment.ActualDelivery;
        existing.RecipientName = shipment.RecipientName;
        existing.CustomerEmail = shipment.CustomerEmail;
        existing.Notes = shipment.Notes;
        if (shipment.Status == ShipmentStatus.Delivered && existing.ActualDelivery == null)
            existing.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return existing;
    }
}
