### 6. Server-side service — `ShipmentTracker/Services/ServerShipmentService.cs`
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
        => await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<Shipment?> GetByIdAsync(int id)
        => await db.Shipments.FindAsync(id);

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";
        shipment.CreatedDate = DateTime.UtcNow;
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var existing = await db.Shipments.FindAsync(shipment.Id)
            ?? throw new InvalidOperationException("Shipment not found");
        existing.Status = shipment.Status;
        existing.Destination = shipment.Destination;
        existing.Origin = shipment.Origin;
        existing.EstimatedDelivery = shipment.EstimatedDelivery;
        existing.ActualDelivery = shipment.ActualDelivery;
        existing.RecipientName = shipment.RecipientName;
        existing.CustomerEmail = shipment.CustomerEmail;
        existing.Notes = shipment.Notes;
        if (shipment.Status == ShipmentStatus.Delivered && existing.ActualDelivery == null)
            existing.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return existing;
    }
}
```

### 7. API Endpoints — `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()))
            .RequireAuthorization();

        group.MapGet("/{id:int}", async (int id, IShipmentService service) =>
        {
            var shipment = await service.GetByIdAsync(id);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/{created.Id}", created);
        }).RequireAuthorization();

        group.MapPut("/{id:int}", async (int id, Shipment shipment, IShipmentService service) =>
        {
            shipment.Id = id;
            var updated = await service.UpdateShipmentAsync(shipment);
            return Results.Ok(updated);
        }).RequireAuthorization();
    }
}
```

