    private List<Shipment> shipments = [];
    private string searchTerm = "";
    private string statusFilter = "";
    private bool loading = true;
    private bool showCreateForm;
    private Shipment newShipment = new();
    private int? editingShipmentId;
    private ShipmentStatus editStatus;

    private List<Shipment> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        .Where(s => string.IsNullOrEmpty(searchTerm) ||
            s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreateForm = false;
        await LoadShipments();
    }

    private void StartEdit(Shipment shipment)
    {
        editingShipmentId = shipment.Id;
        editStatus = shipment.Status;
    }

    private async Task SaveStatus(Shipment shipment)
    {
        shipment.Status = editStatus;
        await ShipmentService.UpdateShipmentAsync(shipment);
        editingShipmentId = null;
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}
