@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, recipient, or destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="LoadShipments">
            <span class="bi bi-arrow-clockwise" aria-hidden="true"></span> Refresh
        </button>
        <button class="btn btn-success ms-2" @onclick="ShowCreateForm">
            <span class="bi bi-plus" aria-hidden="true"></span> New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="newShipment.Origin" />
                    </div>
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="newShipment.Destination" />
                    </div>
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Recipient Name</label>
                        <InputText class="form-control" @bind-Value="newShipment.RecipientName" />
                    </div>
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Customer Email</label>
                        <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                    </div>
                </div>
                <div class="row">
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-3 mb-2">
                        <label class="form-label">Notes</label>
                        <InputText class="form-control" @bind-Value="newShipment.Notes" />
                    </div>
                </div>
                <button type="submit" class="btn btn-primary">Create</button>
                <button type="button" class="btn btn-secondary ms-2" @onclick="() => showCreateForm = false">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (FilteredShipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Recipient</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><strong>@shipment.TrackingNumber</strong></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.RecipientName</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        @if (editingShipmentId == shipment.Id)
                        {
                            <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                            <button class="btn btn-sm btn-success ms-1" @onclick="() => SaveStatus(shipment)">Save</button>
                            <button class="btn btn-sm btn-secondary ms-1" @onclick="() => editingShipmentId = null">Cancel</button>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(shipment)">Update Status</button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment> shipments = [];
    private string searchTerm = "";
    private string statusFilter = "";
    private bool loading = true;
    private bool showCreateForm;
    private Shipment newShipment = new();
    private int? editingShipmentId;
    private ShipmentStatus editStatus;

    private List<Shipment> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        .Where(s => string.IsNullOrEmpty(searchTerm) ||
            s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreateForm = false;
        await LoadShipments();
    }

    private void StartEdit(Shipment shipment)
    {
        editingShipmentId = shipment.Id;
        editStatus = shipment.Status;
    }

    private async Task SaveStatus(Shipment shipment)
    {
        shipment.Status = editStatus;
        await ShipmentService.UpdateShipmentAsync(shipment);
        editingShipmentId = null;
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260601-1001)"
                   @bind="trackingInput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (searched && shipment == null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@lastSearched</strong>. Please check the number and try again.
    </div>
}
else if (shipment != null)
{
    <div class="card">
        <div class="card-header">
            <h4 class="mb-0">Shipment @shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <table class="table">
                        <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
                        <tr><th>Origin</th><td>@shipment.Origin</td></tr>
                        <tr><th>Destination</th><td>@shipment.Destination</td></tr>
                        <tr><th>Created</th><td>@shipment.CreatedDate.ToString("MMM dd, yyyy")</td></tr>
                        @if (shipment.Notes != null)
                        {
                            <tr><th>Notes</th><td>@shipment.Notes</td></tr>
                        }
                    </table>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Status</h5>
                    <div class="mb-3">
                        <span class="badge fs-6 @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    @if (shipment.EstimatedDelivery.HasValue)
                    {
                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                    }
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <p class="text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                    }

                    <h6 class="mt-4">Shipment Progress</h6>
                    @{ var steps = GetProgressSteps(shipment.Status); }
