                    @if (shipment.EstimatedDelivery.HasValue)
                    {
                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                    }
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <p class="text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                    }

                    <h6 class="mt-4">Shipment Progress</h6>
                    @{ var steps = GetProgressSteps(shipment.Status); }
                    <div class="progress mb-2" style="height: 24px;">
                        <div class="progress-bar @GetProgressBarClass(shipment.Status)" role="progressbar"
                             style="width: @steps.percent%">
                            @steps.percent%
                        </div>
                    </div>
                    <div class="d-flex justify-content-between small text-muted">
                        <span>Pending</span>
                        <span>Picked Up</span>
                        <span>In Transit</span>
                        <span>Out for Delivery</span>
                        <span>Delivered</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

